{"type": "edit", "path": "factorials.py", "content": "def factorial(n: int) -> int:
    """Return n factorial."""
    if n < 0:
        raise ValueError('Negative values not allowed')
    if n == 0:
        return 1
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result
"}

